import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect, vi } from "vitest";
import { screen, render, fireEvent } from "@testing-library/react";
import { ErrorState } from "../ErrorState";
const props = {
    buttonText: "Label",
    description: "Description",
    handleButtonOnClick: () => jest.fn(),
    header: "Header",
    subButtonText: "Sub Label",
};
describe("Rapid7 ErrorState", () => {
    it("Should render the Error State with the default image and content", () => {
        render(_jsx(ErrorState, { ...props }));
        expect(screen.getByText("Label")).toBeInTheDocument();
        expect(screen.getByText("Description")).toBeInTheDocument();
        expect(screen.getByText("Header")).toBeInTheDocument();
    });
    it("Should render the Error State with the default image and a second button", () => {
        render(_jsx(ErrorState, { ...props, handleSubButtonOnClick: () => jest.fn() }));
        expect(screen.getByText("Label")).toBeInTheDocument();
        expect(screen.getByText("Description")).toBeInTheDocument();
        expect(screen.getByText("Header")).toBeInTheDocument();
        expect(screen.getByText("Sub Label")).toBeInTheDocument();
    });
    it("Should render the ErrorState with a custom image", () => {
        render(_jsx(ErrorState, { ...props, image: _jsx("img", { alt: "Placeholder Image", src: "https://placehold.co/250x250.png" }) }));
        const image = screen.getByAltText("Placeholder Image");
        expect(screen.getByText("Label")).toBeInTheDocument();
        expect(screen.getByText("Description")).toBeInTheDocument();
        expect(screen.getByText("Header")).toBeInTheDocument();
        expect(image).toHaveAttribute("src", "https://placehold.co/250x250.png");
    });
    it("Should allow an action on the main button click", () => {
        const handleClick = vi.fn();
        render(_jsx(ErrorState, { ...props, handleButtonOnClick: handleClick, image: null }));
        fireEvent.click(screen.getByRole("button"));
        expect(handleClick).toHaveBeenCalledTimes(1);
    });
});
